(() => {
'use strict';
const P=window.Portal,D=window.PartnerElakademin;if(!P||!P.routes['academy-library'])return;
const courses=P.routes.academy,legacy=P.routes['academy-library'],e=P.e;
let section='films';
const sections=[['courses','Kurser & prov'],['calls','Samtalsexempel'],['scripts','Säljmanus'],['invoice','Förstå elfakturan'],['links','Viktiga länkar'],['films','Filmer & handböcker']];
const nav=active=>`<nav class="ar-nav" aria-label="Utbildning och säljstöd">${sections.map(([id,label])=>`<button type="button" data-ar-page="${id}" aria-current="${active===id?'page':'false'}">${label}</button>`).join('')}</nav>`;
function bindNav(){document.querySelectorAll('[data-ar-page]').forEach(b=>b.onclick=()=>{P.learningFilms?.stop();if(b.dataset.arPage==='courses')P.go('academy');else{section=b.dataset.arPage;P.go('academy-library');}document.querySelector('.ar-nav [aria-current="page"]')?.focus();});}
const chapterHref=id=>`elakademin.html?${new URLSearchParams({track:'all',workspace:P.partner,...(P.demoMode?{demo:'inflyttning'}:{})})}#lesson/${encodeURIComponent(id)}`;
const chapterLink=(id,title)=>`<a class="btn btn-secondary" href="${e(chapterHref(id))}" target="_blank" rel="noopener">${e(title)} ↗</a>`;
function films(){const lessons=[{"id": "energi-effekt", "title": "Energi, effekt och rätt enheter", "track": "shared", "introduction": "Alla elavtal handlar till sist om en mängd el, ett pris och villkoren som kopplar ihop dem. Här lär du dig läsa siffrorna innan du väljer produkt. Du behöver ingen teknisk bakgrund. Ta fram en miniräknare och skriv alltid enheten bredvid talet: en korrekt metod blir mycket lättare att kontrollera när varje steg visar vad siffran betyder.", "customer_explanation": {"short": "kW visar hur snabbt ni använder el, medan kWh visar mängden ni har använt. Vi multiplicerar den köpta mängden med priset per kWh. Sedan måste vi se vilka avgifter och andra kostnader som ingår innan vi kan tala om hela fakturan.", "detailed": "En ugn som använder 10 kW i två timmar förbrukar 20 kWh. För er årskostnad behöver vi den uppmätta eller förväntade energimängden, inte bara maskinernas märkplåtar. Om den mängden är 120 MWh räknar vi med 120 000 kWh. Ett pris på 80 öre ger då 96 000 kronor för just den prisdelen. Jag visar elhandel, nät och skatter var för sig så att beräkningen går att följa."}}, {"id": "elhandel-elnat", "title": "Elhandel, elnät och hela elräkningen", "track": "shared", "introduction": "'Elbolaget' och 'elräkningen' kan omfatta flera roller och kostnadsdelar. Här gör du sambanden begripliga: vem ansvarar för vad, vad kunden kan välja och vilka belopp ett elhandelsavtal påverkar. Målet är en läsbar faktura utan att kunden behöver kunna hela branschen.", "customer_explanation": {"short": "Ni betalar dels för elen enligt ert elhandelsavtal, dels för nätet som transporterar den. Skatt och moms är ytterligare delar. Vi kan jämföra och förändra elhandelsavtalet, men ska visa nät och skatter separat så att ni förstår hela kostnaden.", "detailed": "Byte av elhandlare ändrar hur elen prissätts i ert avtal, medan den anslutna anläggningen ligger kvar i samma lokala nät. På elhandeln räknar vi både kWh-priset och fasta avgifter. Om vi sänker den delen med 600 kronor är det 600 kronor som påverkas i vår jämförelse, inte automatiskt samma procent på hela fakturan. Vi använder era faktiska underlag för nät och skatt och anger tydligt hur moms behandlas."}}, {"id": "elmarknad", "title": "Så fungerar elmarknaden och spotpriset", "track": "shared", "introduction": "Elpriset är ett resultat av en marknad som måste hantera både plats och tid. Det gör att en enda siffra i en nyhetsrubrik sällan räcker för att beskriva kundens pris. Här bygger vi en enkel modell för varför priset rör sig och vilka frågor som gör ett prisbesked användbart. Målet är förståelse, inte att kunna förutsäga morgondagens marknad.", "customer_explanation": {"short": "Elpriset bestäms av hur mycket el marknaden behöver, vilket utbud som finns och vad som kan överföras mellan områden. Priset gäller en viss kvart i ert elområde. Er egen kostnad beror dessutom på när och hur mycket ni använder samt vad som ingår i ert avtal.", "detailed": "En prisrubrik beskriver ofta en begränsad del av marknaden. För er anläggning behöver vi rätt område och tid, därefter er förbrukning och avtalets kostnadsdelar. Prissäkring av framtiden använder andra prisreferenser än dagens spotnotering. Jag visar därför både vad priset avser och vilka delar som fortfarande kan förändras, utan att behandla en prognos som ett löfte."}}, {"id": "forbrukningsprofil", "title": "När elen används: kvart, dygn och månad", "track": "shared", "introduction": "Årsförbrukningen berättar hur mycket el kunden använder. Profilen berättar när. Två kunder kan använda lika många kWh men få olika energikostnad, därför att deras mängder hamnar i olika prisintervall. Här räknar du fram kundens eget snitt, skiljer säsong från dygn och övar på att bedöma om en verklig lastflytt kan vara meningsfull.", "customer_explanation": {"short": "Det räcker inte att veta hur mycket el ni använder på ett år. Vi behöver också veta när. Mycket användning under dyra intervall höjer ert snitt, och mycket under billiga sänker det. Vi räknar därför pris gånger mängd för varje relevant period.", "detailed": "Vi tittar på två nivåer: hur inköpt el fördelas mellan månaderna och när den används inom dygnet. Er avtalsmodell avgör hur dessa mönster påverkar priset. Om ni kan flytta användning prövar vi en realistisk plan och tar med nätets villkor. En månadsutjämning av en säkrad del hanterar inte automatiskt hela dygnsprofilen eller andra fakturadelar."}}, {"id": "pris-och-risk", "title": "Pris, prissäkring och risken som finns kvar", "track": "shared", "introduction": "Ett prisupplägg hjälper kunden hantera marknadsrisk men tar inte bort alla osäkerheter. Här förklarar du vad som är känt, vilka mängder det gäller och vad som påverkar kostnaden. Det behövs för både trygghet och marknadsexponering.", "customer_explanation": {"short": "Prissäkring bestämmer vissa prisdelar för en avtalad mängd och period. Det minskar exponeringen mot högre marknad i de delarna, men de följer inte med ned vid prisfall. Andra delar och mängden ni faktiskt använder kan fortfarande ändra slutkostnaden.", "detailed": "Vi ska vara tydliga med vad procenten avser. Om vi säkrar 80 MWh utifrån 100 MWh underlag är det inte ett löfte om att 80 procent av hela räkningen är fast. Använder ni mer ändras den faktiska täckningen. Vi går igenom säkrade referenser, osäkrad volym, profil och avgifter och visar både högre och lägre marknad, så att valet passar ert behov av förutsägbarhet."}}, {"id": "kundens-behov", "title": "Från kundens behov till en rättvis avtalsjämförelse", "track": "shared", "introduction": "En bra rekommendation börjar med kundens mål, accepterad variation och faktiska elanvändning. Här använder du grunderna i kundsamtalet: ställer konkreta frågor, gör jämförbara beräkningar och hjälper kunden förstå konsekvenserna innan ett produktval föreslås.", "customer_explanation": {"short": "Vi börjar med er budget och hur ni använder el, sedan jämför vi alternativen på samma mängd och kostnadsdelar. Jag visar vad som kan förändras och vad som blir mer förutsägbart. Målet är ett val ni förstår och som passar era förutsättningar.", "detailed": "Först vill jag förstå hur stora prisvariationer ni accepterar och vilka förändringar som väntar i verksamheten. Därefter använder vi rätt mätpunkter, månads- och kvartdata och ert nuvarande avtal. Om beräkningen är ett scenario märker vi det som scenario. Jag förklarar både skälet till förslaget och vilka ändringar i era behov som skulle göra ett annat alternativ mer lämpligt."}}, {"id": "kvartspris", "title": "Kvartspris – när användningstiden påverkar priset", "track": "shared", "introduction": "Kvartspris kopplar energikostnaden till när kunden faktiskt använder el. Här lär du dig läsa den kopplingen, räkna på den och bedöma om kunden kan påverka den. Modellen passar inte automatiskt en viss bostad eller bransch. Det avgörande är kundens mätdata, användningstider, möjliga förändringar och förmåga att hantera prisvariation.", "customer_explanation": {"short": "Med Kvartspris följer energikostnaden priset och din användning i varje kvart. Använder du mer när priset är högt blir ditt energisnitt högre. Du kan ibland påverka kostnaden genom att flytta användning, men marknadspriset varierar och andra elkostnader tillkommer enligt dina villkor.", "detailed": "Vi räknar ihop vad du har använt i varje kvart till priset för samma kvart i ditt elområde. Därför behöver vi förstå när du använder el och vilka laster du kan flytta. Vi jämför samma volym och kostnadsdelar, tittar på budgettålighet och kontrollerar eventuella effekter på nätkostnaden. Modellen ger en direkt tidskoppling, men ingen garanti för ett visst framtida snittpris eller en bestämd besparing."}}, {"id": "rorligt-pris", "title": "Rörligt pris – ett gemensamt pris som varierar mellan månader", "track": "shared", "introduction": "Rörligt pris följer den avtalade gemensamma månadsmodellen. Priset fastställs i efterhand och kan förändras från månad till månad. Lektionen visar hur samma pris per kWh kan ge olika belopp, hur avgifter påverkar jämförelsen och varför egen lastflytt inte ger samma direkta individuella spotvinst som med Kvartspris.", "customer_explanation": {"short": "Med Rörligt pris får du det gemensamma månadspriset enligt avtalet. Det fastställs i efterhand och kan ändras mellan månader. Din mängd el och avtalade avgifter påverkar beloppet. Modellen skiljer sig från ett pris som räknas direkt från din egen användning i varje kvart.", "detailed": "Vi går igenom vilken månadsreferens och vilka kostnadsdelar ditt erbjudande använder. Sedan räknar vi på din förbrukning över året och tar med avgifter på ett jämförbart sätt. Om du vill påverka kostnaden genom att flytta användning till särskilda kvartar behöver vi även jämföra med en individuell kvartsmodell. Rörligt pris följer marknaden, så du behöver acceptera både lägre och högre månadspriser."}}, {"id": "fastpris", "title": "Fastpris – ett känt enhetspris med tydlig omfattning", "track": "shared", "introduction": "Fastpris ger ett avtalat elhandelspris för en uttryckligt definierad omfattning och leveransperiod. Förutsägbarheten gäller priset på de avtalade delarna. Den betyder inte automatiskt samma faktura varje månad eller ett pris som alltid blir lägre än marknaden. Här lär du dig förklara både nyttan och avvägningen utan att förväxla Fastpris med en begränsad komponentprissäkring.", "customer_explanation": {"short": "Fastpris gör priset på de avtalade elhandelsdelarna känt för den avtalade perioden. Det gör budgeteringen enklare, men beloppet beror fortfarande på hur mycket el du använder. Om marknaden sjunker följer det fasta priset inte automatiskt med ned. Elnät, skatt och moms hanteras separat.", "detailed": "Vi går igenom exakt vilka elhandelsdelar ditt erbjudande omfattar och vilken period det gäller. Därefter räknar vi på din förväntade förbrukning och visar både ett högre och ett lägre rörligt marknadsutfall. Fastpris kan vara relevant när ett känt enhetspris väger tungt för budgeten och du accepterar att marknaden senare kan bli billigare. Förändringar i volym och verksamhet behöver bedömas mot dina faktiska avtalsvillkor."}}, {"id": "opti", "title": "Opti – det lägre av två jämförbara månadsutfall", "track": "consumer", "introduction": "Opti använder Kvartspris som grund och jämför efter månadens slut med avtalets vanliga rörliga månadspris. Det lägre jämförbara alternativet väljs för hela månaden. Lektionen gör jämförelsen synlig från mätvärden till resultat och visar varför det precisa kundlöftet skiljer sig från både kvartvis växling och ett fast pristak.", "customer_explanation": {"short": "Med Opti räknar vi efter månaden både ditt eget kvartsvägda utfall och avtalets vanliga rörliga månadsalternativ för samma användning och kostnadsdelar. Du får det lägre av de två för hela månaden. Priset kan fortfarande variera; vi väljer inte minimum i varje kvart och lovar inte ett fast pristak.", "detailed": "Vi börjar med hur du faktiskt använder el i varje kvart och räknar ihop månaden. Sedan beräknar vi avtalets månadsalternativ för samma faktiska månadsvolym. Jämförelsen görs med samma definierade komponenter. Det ger möjlighet att få nyttan av en gynnsam kvartprofil och använda månadsalternativet om det blir lägre. Båda alternativen följer marknaden, och avgifter eller andra elkostnader utanför jämförelsen behöver redovisas separat."}}, {"id": "vintersakrat", "title": "Vintersäkrat – fast vinterdel och kvartsvägd sommardel", "track": "consumer", "introduction": "Vintersäkrat kombinerar fast elhandelspris oktober–mars med Kvartspris april–september som standard. Andra perioder kräver uttryckligt avtal. Här lär du dig läsa kalendern, förstå hela vinteromfattningen och räkna på året med köpta volymer och fortsatt sommarvariation.", "customer_explanation": {"short": "Vintersäkrat har normalt fast elhandelspris oktober–mars, inklusive dygnsprofilen, och Kvartspris april–september. Andra månader behöver vara uttryckligen avtalade. Du får en mer förutsägbar vinterdel, men sommarpriset och mängden el påverkar årskostnaden. Elnät, skatt och moms omfattas inte av säkringen.", "detailed": "Vi analyserar din köpta årsprofil och önskad förutsägbarhet. Vinterdelen är fast enligt avtalet; sommaren följer egen användning och kvartpriser. Flera sommarutfall visar risken. Kalender, avgifter och förändringsvillkor kontrolleras i erbjudandet. Det är inte ett fast årsbelopp eller löpande val av billigaste pris."}}, {"id": "individuell-indexportfolj", "title": "Individuell indexportfölj – en egen inköpsplan över tid", "track": "business", "introduction": "Individuell indexportfölj passar som samtalsalternativ när ett företag vill ha en egen, strukturerad inköpsplan. Här lär du dig vad som planeras, hur volymunderlaget påverkar planen och varför ett inköpssnitt behöver skiljas från fakturapriset. Målet är att kunna förklara nyttan och riskerna så att kunden förstår vad den väljer.", "customer_explanation": {"short": "Ni får en egen inköpsplan där regelstyrda köp bygger upp prissäkringen över tid. Vi kommer överens om volymer, perioder och hur stor del som ska säkras. Det sprider inköpstidpunkterna, men kan bli dyrare än osäkrat om marknaden faller.", "detailed": "Vi kartlägger nätinköp och förändringar per månad. Sedan bestäms individuella grader och horisont. Standardhorisonten 24 månader är inte avtalslängden. Slutkostnaden följer offertens prisformel, genomförda köp, förbrukning och övriga komponenter."}}, {"id": "pool-trygg", "title": "Pool Trygg – gemensamma indexinköp med rörlig del", "track": "business", "introduction": "Pool Trygg samlar elinköp i en gemensam, planerad strategi. Namnet kan låta som ett löfte om en helt fast kostnad, men strategin innehåller både stegvisa indexköp och en rörlig del. Den här lektionen hjälper dig att förklara fördelningen korrekt och visa varför två poolkunder ändå kan få olika årssnitt.", "customer_explanation": {"short": "Pool Trygg bygger på gemensamma, regelstyrda inköp för 80 procent av den förväntade volymen och 20 procent rörligt. Det sprider indexdelens inköp över tid. Det ger ingen garanti om lägst pris eller helt fast kostnad.", "detailed": "Vi kontrollerar prisomfattning, genomförd säkring och kvarvarande inköpsplan. Månadsförbrukning och kundvillkor påverkar utfallet. Köp kan vara fördelaktiga vid uppgång och dyrare än osäkrat vid prisfall. Kontrollera aktuell horisont, avtalslängd och avvikelseregler."}}, {"id": "pool-offensiv", "title": "Pool Offensiv – index, aktiva beslut och rörlig exponering", "track": "business", "introduction": "Pool Offensiv kombinerar indexköp, aktiva marknadsbedömningar och rörlig exponering. Här visar vi gynnsamma och ogynnsamma scenarier. Kunden behöver förstå mandatet och att aktiv förvaltning inte garanterar billigast el.", "customer_explanation": {"short": "Pool Offensiv fördelar den förväntade volymen på 40 procent regelstyrda indexköp, 40 procent aktiva marknadsbedömningar och 20 procent rörligt. Ni deltar i gemensam förvaltning. De aktiva besluten kan ge både bättre och sämre utfall än en annan strategi.", "detailed": "Vi verifierar mandat, position och prisomfattning. Strategin är inte faktisk säkringsgrad eller fast slutpris. Budgeten behöver tåla kvarvarande exponering och att aktivdelen blir dyrare än jämförelsen."}}, {"id": "kraftringen-direkt", "title": "Kraftringen Direkt – välj tillfälle, förstå vad som säkras", "track": "business", "introduction": "Direkt låter kunden välja ett inköpstillfälle och säkra SYS/EPAD för avtalad mängd och framtida period. Du lär dig förklara beslutet, räkna volym och visa kvarvarande kostnadsvariation för en kund utan erfarenhet av elinköp.", "customer_explanation": {"short": "Med Direkt väljer ni ett tillfälle att säkra SYS och elområdesskillnaden för en överenskommen mängd och period. Det ger större förutsägbarhet för de delarna. Dygnsprofil, osäkrad volym och andra prisdelar ligger separat. Säkrad nivå följer inte automatiskt med ned om marknaden faller.", "detailed": "Vi utgår från framtida förbrukning och period. Ni accepterar SYS/EPAD-nivå vid ett tillfälle. Vi anger mängd, återstående risk och avvikelseregler. Behöver ni gemensamt komponentpris jämför vi med Stabil."}}, {"id": "kraftringen-stabil", "title": "Kraftringen Stabil – samma säkring, förbrukningsvägt komponentpris", "track": "business", "introduction": "Stabil säkrar SYS/EPAD vid ett tillfälle för avtalad mängd och period. Förväntad månadsprofil ger dessutom ett gemensamt pris på säkrad del. Du lär dig beräkna utjämningen och förklara kvarvarande variation.", "customer_explanation": {"short": "Stabil säkrar SYS och elområdesskillnad vid ett tillfälle. Förväntad månadsförbrukning ger gemensamt pris på avtalad säkrad del. Profil, osäkrat och övrigt ligger separat; använd mängd påverkar fakturan.", "detailed": "Månader med stor förväntad mängd väger mer i komponentpriset. Varje överenskommen säkrad kWh får samma SYS/EPAD-pris, utan besparing genom utjämningen i sig. Ändrad faktisk profil ändrar inte detta pris för avtalad säkrad mängd. Andra kostnader och avvikelser följer prisbilagan. Därför behöver vi er framtida månadsplanering."}}, {"id": "kundfall-foretag", "title": "Företagskunden: från behov till motiverat produktval", "track": "business", "introduction": "Nu ska du använda grunderna och produkterna i ett sammanhängande kundmöte. Målet är att lämna en begriplig, motiverad rekommendation. Ett bra svar visar vad du vet, vilken information som saknas och hur nästa beslut kan fattas. Kundfallen och priserna i kapitlet är påhittade undervisningsexempel.", "customer_explanation": {"short": "Vi börjar med hur mycket el ni använder, när ni använder den och vilken risk ni vill hantera. Sedan jämför vi samma delar av priset. Prissäkring kan ge mer förutsägbarhet på de delar som omfattas, men mängden el och övriga komponenter påverkar fortfarande kostnaden.", "detailed": "För ert företag behöver vi först skilja stigande pris från högre förbrukning. Direkt och Stabil säkrar SYS och elområdesskillnaden för överenskommen volym och period vid ett tillfälle. Stabil räknar dessutom in er förväntade månadsprofil i ett gemensamt komponentpris. Portföljlösningar sprider inköpsbesluten på andra sätt. Vi visar vad som ligger kvar öppet i varje alternativ och använder er aktuella offert för alla priser och avvikelsevillkor."}}, {"id": "kundfall-privat", "title": "Privatkunden: ett begripligt val och ett bra samtal", "track": "consumer", "introduction": "I ett bra konsumentsamtal ska kunden förstå sitt val, inte bara höra ett produktnamn. Här använder du produktkunskapen i tre hushållsfall och ett telefonrollspel. Alla namn, priser och dialoger är fiktiva utbildningsexempel. Verkliga inspelningar finns bara när de har lagts till i samtalsbiblioteket enligt verksamhetens godkända rutin.", "customer_explanation": {"short": "Vi väljer avtalsmodell utifrån hur du använder el, hur mycket du kan flytta och hur stor prisvariation du vill acceptera. Sedan visar vi vad priset omfattar och vad som fortfarande kan ändras. Ett fast pris per kilowattimme betyder inte att räkningen blir lika stor varje månad.", "detailed": "Kvartspris följer dina uttag kvart för kvart, Rörligt pris följer avtalets månadsmodell och Fastpris bestämmer energihandelspriset enligt avtalet för perioden. Opti jämför två hela månadsutfall på samma bas. Vintersäkrat kombinerar en fast vinterdel med en kvartssatt sommardel. Vi räknar med dina kWh och eventuella avgifter och håller elnät, skatt och moms tydligt åtskilda."}}];return `<div class="ar-intro"><span class="eyebrow">Se, lyssna och repetera</span><h1>Filmer & handböcker</h1><p>Här finns de tidigare kapitelfilmerna kvar, tillsammans med presentationen och läsmaterialet. De öppnas i Elakademin. Godkännanden för orderläggning hanteras under Kurser & prov.</p></div><div class="ar-downloads">${[['elakademin-material/Kraftringen-Elakademin-Utbildning-v2.pptx','PowerPoint-presentation'],['elakademin-material/Kraftringen-Elakademin-Sjalvstudier-v2.pdf','Handbok · PDF'],['elakademin-material/Kraftringen-Grundunderlag-v1.pdf','Grundunderlag · PDF']].map(([url,label])=>`<a href="${url}" class="btn btn-secondary" target="_blank" rel="noopener">${label} ↗</a>`).join('')}</div><div class="ar-grid">${lessons.map((l,i)=>`<article class="ar-card"><span class="eyebrow">FILM ${String(i+1).padStart(2,'0')} · ${l.track==='business'?'Företag':l.track==='consumer'?'Privatkund':'Grundkunskap'}</span><h2>${e(l.title)}</h2><p>${e((l.customer_explanation?.short||l.introduction||'Se filmen och repetera med kapitlets exempel.').slice(0,230))}</p>${chapterLink(l.id,'Öppna filmen')}</article>`).join('')}</div><details class="ar-legacy"><summary>Äldre demokurser, bokmärken och klarmarkeringar</summary><p>Dina äldre framsteg finns kvar. De är separata från utbildningsprogrammets kunskapsprov.</p><button class="btn btn-secondary" data-ar-legacy>Öppna tidigare utbildningsöversikt</button></details>`;}
function calls(){return `<div class="ar-intro"><span class="eyebrow">Lyssna och diskutera</span><h1>Samtalsexempel</h1><p>Jämför vad säljaren säger, vad kunden faktiskt behöver och hur samtalet avslutas. Egna inspelningar lagras lokalt för partnern och delas inte automatiskt med kollegor.</p></div><div class="ar-grid"><article class="ar-card"><span class="eyebrow">Fiktivt dialogexempel · bra arbetssätt</span><h2>”Jag vill bara ha billigast el”</h2><blockquote>”Vilken del vill du minska: kostnaden per kWh, hela fakturan eller risken för stora variationer? Ska vi först titta på hur och när du använder el?”</blockquote><details><summary>Vad gör detta bra?</summary><p>Säljaren klargör målet innan en produkt föreslås. Kunden får hjälp att skilja pris, förbrukning och risk. Nästa steg är att granska underlaget och jämföra på samma grunder.</p></details></article><article class="ar-card"><span class="eyebrow">Fiktivt dialogexempel · att förbättra</span><h2>”Det här blir alltid billigast”</h2><blockquote>”Välj vår lösning så blir hela din elräkning lägre och du slipper prisrisken.”</blockquote><details><summary>Varför fungerar detta inte?</summary><p>Påståendet saknar underlag och blandar elhandel med hela elkostnaden. Säljaren behöver förklara kvarvarande risker och vilka kostnader erbjudandet faktiskt påverkar, och fråga efter kundens behov.</p></details></article></div>${P.b2cCalls?.eligible()?P.b2cCalls.render():'<div class="ar-card"><h2>Inspelade samtal</h2><p>Det befintliga lokala ljudbiblioteket är tillgängligt för partners med konsumentförsäljning. Dialogexemplen ovan är skrivna övningar, inte inspelningar av verkliga kunder.</p></div>'}`;}
function scripts(){return `<div class="ar-intro"><span class="eyebrow">Stöd i kunddialogen</span><h1>Säljmanus</h1><p>Använd frågorna som samtalsstöd. Anpassa orden till kunden och kontrollera erbjudandets aktuella villkor före en rekommendation. Förslagen nedan är övningsmanus.</p></div><div class="ar-grid">${[
['Öppna och förstå','Vad vill du få bättre kontroll över i ditt elavtal?','Fråga om förbrukning, säsong, nuvarande avtal och vad kunden vill uppnå. För företaget: vilka anläggningar och vilka förändringar planeras?','Vilken uppgift behöver vi först för att kunna jämföra rättvist?'],
['Förklara och jämför','Vi delar upp jämförelsen i kostnad, risk och flexibilitet.','Beskriv vad som prissätts, vilka avgifter som tillkommer och vilka risker som finns kvar. Undvik att beskriva en målsatt säkringsgrad som en garanti.','Vill du prioritera att följa marknaden eller en större förutsägbarhet – och vad menar du med det?'],
['Sammanfatta nästa steg','Så här har jag förstått dina behov …','Sammanfatta kundens egna mål och de antaganden ni behöver verifiera. Skilj offert, godkännande och leveransstart. Lova inte ett startdatum som inte är bekräftat.','Vilket underlag ska vi kontrollera och när ska vi följa upp?']
].map(([h,line,guide,q],i)=>`<article class="ar-card"><span class="eyebrow">${i+1} · Samtalsstöd</span><h2>${h}</h2><blockquote>”${line}”</blockquote><p>${guide}</p><strong>Följdfråga</strong><p>”${q}”</p></article>`).join('')}</div>`;}
const invoiceParts=[['Elenergi','400 kWh × 1,25 kr','500 kr','Energimängd multiplicerad med antaget energipris. Kontrollera period, avtalstyp och om priset är ett förbrukningsvägt utfall.'],['Påslag','400 kWh × 0,05 kr','20 kr','Antaget rörligt påslag. Jämför vad som ingår i påslaget och vilka övriga avtalade kostnader som kan tillkomma.'],['Fast avgift','En månad × 40 kr','40 kr','En fast avgift är inte beroende av kWh i det här exemplet. Kontrollera fakturans period.']];
function invoice(){return `<div class="ar-intro"><span class="eyebrow">Förklara rad för rad</span><h1>Förstå elfakturan</h1><p>En klickbar exempelfaktura hjälper dig att skilja elhandel från elnät och skatter. Alla tal är påhittade och anges exklusive moms. Detta är ingen aktuell prislista.</p></div><div class="ar-invoice"><section class="ar-card"><h2>Exempel · en månads elhandel</h2><p>Välj en rad för förklaringen.</p>${invoiceParts.map(([title,calc,total],i)=>`<button class="ar-invoice-row" data-ar-invoice="${i}" aria-pressed="${i===0}"><span><strong>${title}</strong><small>${calc}</small></span><b>${total}</b></button>`).join('')}<div class="ar-invoice-total"><span>Summa i exemplet</span><strong>560 kr</strong></div><small>Exklusive moms, elnät, energiskatt och eventuella andra avtalade kostnader.</small></section><section class="ar-card" aria-live="polite" id="ar-invoice-explain"><h2>${invoiceParts[0][0]}</h2><p>${invoiceParts[0][3]}</p></section></div><div class="ar-grid"><article class="ar-card"><h2>Elnätet är en annan del</h2><p>Nätkostnaden avser anslutning och transport. Den kan innehålla fast avgift, överföringsavgift och effektavgift enligt nätavtalet. Ett byte av elhandlare ändrar inte vilket nät kunden är ansluten till.</p></article><article class="ar-card"><h2>Skatter och jämförbarhet</h2><p>Kontrollera hur energiskatt och moms redovisas. Jämför samma period, energimängd, kostnadsposter och momsgrund. Ett spotpris är inte hela fakturans pris.</p></article><article class="ar-card"><h2>Kundens vanligaste missförstånd</h2><p>Fast pris per kWh betyder inte samma totalbelopp varje månad. Mer förbrukning och andra avgifter kan ändra beloppet.</p>${chapterLink('pris-och-risk','Fördjupa prisförståelsen')}${chapterLink('elhandel-elnat','Se den tidigare fakturaförklaringen')}</article></div>`;}
function links(){return `<div class="ar-intro"><span class="eyebrow">Hitta rätt källa</span><h1>Viktiga länkar</h1><p>Använd aktuella källor när en kundfråga behöver kontrolleras. Kursens produktbeskrivningar ersätter inte ett aktuellt erbjudande eller avtalsvillkor.</p></div><div class="ar-grid">${Object.values(window.PartnerLearningContent.sources).map(([title,url])=>`<article class="ar-card"><h2>${e(title)}</h2><a href="${e(url)}" target="_blank" rel="noopener">Öppna källa ↗</a></article>`).join('')}</div><div class="ar-downloads"><button class="btn btn-secondary" data-go="products">Produkter i portalen</button><button class="btn btn-secondary" data-go="support">Hjälp & support</button></div>`;}
function render(){if(section==='legacy')return nav('films')+legacy.render();return `<section class="ar-page">${nav(section)}${({films,calls,scripts,invoice,links}[section]||films)()}<p class="ar-foot">Säljstöd och repetition ger inga automatiska provgodkännanden. Dina utbildningskrav finns under Kurser & prov.</p></section>`;}
function bind(){bindNav();if(section==='legacy')legacy.bind?.();if(section==='calls')P.b2cCalls?.bind();document.querySelector('[data-ar-legacy]')?.addEventListener('click',()=>{section='legacy';P.render();});document.querySelectorAll('[data-ar-invoice]').forEach(b=>b.onclick=()=>{const [title,,,explanation]=invoiceParts[Number(b.dataset.arInvoice)];document.querySelectorAll('[data-ar-invoice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#ar-invoice-explain').innerHTML=`<h2>${title}</h2><p>${explanation}</p>`;});}
P.register('academy',{render:()=>nav('courses')+courses.render(),bind:()=>{courses.bind?.();bindNav();}});
P.register('academy-library',{render,bind});
})();
